from __future__ import annotations
import csv, hashlib, json, os
from pathlib import Path
import numpy as np
from astropy.io import fits
from PIL import Image, ImageDraw, ImageFont

ROOT = Path.cwd(); OUT = ROOT / "dist/science/kerr-high-energy-measured-import-v435"; ARTIFACT = OUT / "measured-import.json"; ORACLE = OUT / "measured-import-oracle.json"; CONTRACT = OUT / "measured-import-contract.json"; MANIFEST_FIXTURE = OUT / "signed-fixture-manifest.json"; CSV_PATH = OUT / "measured-import-gates.csv"; FITS_PATH = OUT / "measured-import-status.fits"; PNG_PATH = OUT / "measured-import-firewall.png"; EXPORT_MANIFEST = OUT / "export-manifest.json"
def file_sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(1024 * 1024): digest.update(chunk)
    return digest.hexdigest()
def atomic(path: Path, payload: bytes) -> None:
    temporary = path.with_name(f"{path.name}.{os.getpid()}.part"); temporary.write_bytes(payload); temporary.replace(path)
def write_fits(rows: list[dict[str, str]]) -> None:
    primary = fits.PrimaryHDU(); primary.header["HASIMAGE"] = (False, "No detector image"); primary.header["FIXTURE"] = (True, "Signed validator fixture only"); primary.header["BINDINGS"] = (6, "v434 bindings"); primary.header["SIGOK"] = (True, "Ed25519 fixture signature"); primary.header["HASHOK"] = (True, "File hashes verified"); primary.header["MEASPACK"] = (False, "No measured authority pack"); primary.header["IMPORTED"] = (False, "Import not attempted"); primary.header["ADMITTED"] = (False, "Science admission blocked"); primary.header["SCIAPPL"] = (0, "Science applications"); primary.header["DENSE"] = (False, "Dense remains 0/49")
    table = fits.BinTableHDU.from_columns([fits.Column(name="GATE_ID", format="32A", array=np.asarray([row["gateId"] for row in rows], dtype="S32")), fits.Column(name="VALIDATED", format="L", array=np.asarray([row["validatorPassed"] == "true" for row in rows], dtype=bool)), fits.Column(name="SCOPE", format="20A", array=np.asarray([row["authorityScope"] for row in rows], dtype="S20")), fits.Column(name="MEASURED", format="L", array=np.zeros(len(rows), dtype=bool)), fits.Column(name="IMPORTED", format="L", array=np.zeros(len(rows), dtype=bool)), fits.Column(name="ADMITTED", format="L", array=np.zeros(len(rows), dtype=bool))], name="IMPORT_GATES")
    temporary = FITS_PATH.with_name(f"{FITS_PATH.name}.{os.getpid()}.part"); fits.HDUList([primary, table]).writeto(temporary, overwrite=True); temporary.replace(FITS_PATH)
def write_png(rows: list[dict[str, str]]) -> None:
    width, height = 1800, 1080; image = Image.new("RGB", (width, height), (3, 8, 10)); draw = ImageDraw.Draw(image); font = ImageFont.load_default(); draw.rectangle((0, 0, width - 1, height - 1), outline=(46, 87, 92), width=1); draw.text((56, 34), "V435 SIGNED CONTENT-ADDRESSED IMPORT FIREWALL", fill=(220, 252, 250), font=font); draw.text((56, 60), "ED25519 + FILE SHA + PATH SAFETY + V434 BINDINGS | NO PACK IMPORTED", fill=(45, 212, 191), font=font)
    for index, row in enumerate(rows):
        column, line = index % 4, index // 4; x, y = 56 + column * 425, 150 + line * 225; passed = row["validatorPassed"] == "true"; draw.rectangle((x, y, x + 382, y + 172), fill=(4, 18, 20), outline=(44, 104, 108) if passed else (133, 92, 45), width=2); draw.text((x + 18, y + 22), f"0{index + 1}  {row['gateId'].upper()}", fill=(153, 246, 228) if passed else (253, 186, 116), font=font); draw.text((x + 18, y + 76), "VALIDATOR PASS" if passed else "NOT RUN", fill=(94, 234, 212) if passed else (251, 146, 60), font=font); draw.text((x + 18, y + 120), f"scope: {row['authorityScope']}", fill=(115, 139, 141), font=font)
    draw.rectangle((56, 720, 1744, 968), fill=(18, 10, 5), outline=(153, 91, 35), width=2); draw.text((86, 762), "IMPORT STATUS", fill=(191, 157, 116), font=font); draw.text((86, 812), "NOT ATTEMPTED — NO MEASURED PACK", fill=(251, 113, 133), font=font); draw.text((86, 862), "Signature and hash closure prove transport integrity only; measured validation and review remain required.", fill=(156, 163, 161), font=font); draw.text((56, 1030), "SCIENCE ADMISSION BLOCKED · SCIENCE APPLICATIONS 0 · DENSE 0/49", fill=(112, 169, 166), font=font)
    temporary = PNG_PATH.with_name(f"{PNG_PATH.name}.{os.getpid()}.part"); image.save(temporary, format="PNG", optimize=False, compress_level=9); temporary.replace(PNG_PATH)
def main() -> None:
    artifact = json.loads(ARTIFACT.read_text(encoding="utf-8")); oracle = json.loads(ORACLE.read_text(encoding="utf-8")); contract = json.loads(CONTRACT.read_text(encoding="utf-8"));
    with CSV_PATH.open("r", encoding="utf-8", newline="") as handle: rows = list(csv.DictReader(handle))
    if len(rows) != 8 or sum(row["validatorPassed"] == "true" for row in rows) != 6 or any(row["measuredPackPresent"] != "false" or row["importAttempted"] != "false" or row["scienceAdmitted"] != "false" or row["scienceResponseApplications"] != "0" for row in rows): raise RuntimeError("v435-csv-boundary")
    if artifact["view"]["gates"]["requiredBindingCount"] != 6 or artifact["view"]["fixture"]["signatureVerified"] is not True or artifact["view"]["counts"]["importAttemptCount"] != 0 or artifact["view"]["scienceBoundary"]["admitted"] is not False or oracle["counts"]["rejectedMutationCount"] != 6 or contract["admission"]["importAttempted"] is not False: raise RuntimeError("v435-boundary")
    write_fits(rows); write_png(rows)
    exports = {"json": {"path": ARTIFACT.name, "sha256": file_sha(ARTIFACT), "semantic": "signed-import-summary-and-boundary"}, "oracle": {"path": ORACLE.name, "sha256": file_sha(ORACLE), "semantic": "signed-fixture-and-mutations"}, "contract": {"path": CONTRACT.name, "sha256": file_sha(CONTRACT), "semantic": "signed-offline-import-contract"}, "manifest": {"path": MANIFEST_FIXTURE.name, "sha256": file_sha(MANIFEST_FIXTURE), "semantic": "signed-validator-fixture-manifest"}, "csv": {"path": CSV_PATH.name, "sha256": file_sha(CSV_PATH), "semantic": "import-gate-status"}, "fits": {"path": FITS_PATH.name, "sha256": file_sha(FITS_PATH), "semantic": "import-status-no-detector-image"}, "png": {"path": PNG_PATH.name, "sha256": file_sha(PNG_PATH), "semantic": "import-firewall-diagram-not-instrument-performance"}}
    manifest = {"version": "v435-kerr-high-energy-measured-import-export-manifest-v1", "artifactSha256": artifact["artifactSha256"], "exports": exports, "requiredBindingCount": 6, "signedFixtureSignatureVerified": True, "signedFixtureFileHashesVerified": True, "mutationCount": 6, "rejectedMutationCount": 6, "measuredPackCount": 0, "importAttemptCount": 0, "measuredResponseAuthority": "unavailable", "measuredLikelihoodAuthority": "unavailable", "scienceAdmission": "blocked-no-measured-authority-pack-imported", "scienceResponseApplicationCount": 0, "denseShardExecuted": False}
    atomic(EXPORT_MANIFEST, (json.dumps(manifest, indent=2, ensure_ascii=False) + "\n").encode("utf-8")); print(json.dumps({"status": "exported-v435-signed-measured-import-firewall", "artifactSha256": artifact["artifactSha256"], "bindings": "6/6", "signature": "verified", "mutations": "6/6-rejected", "importAttempts": 0, "scienceAdmission": "blocked-no-measured-authority-pack-imported", "scienceApplications": 0}, indent=2))
if __name__ == "__main__": main()
